// Package gen turns a scan result into the single generated file that wires an
// app's routes and hooks into pocketkit at init() time.
package gen

import (
	"bytes"
	"fmt"
	"go/format"
	"sort"
	"strconv"
	"strings"

	"github.com/FiretailHosting/pocketkit/internal/scan"
)

// Header marks the generated file. `go generate`'s convention, so tooling and
// code review both recognise the file as machine-written.
const Header = "// Code generated by pocketkit. DO NOT EDIT."

// File renders the generated source for the given scan result.
//
// pkgName is the package clause of the app's main package (normally "main").
func File(res *scan.Result, pkgName string) ([]byte, error) {
	var b bytes.Buffer

	aliases := map[string]string{}
	for i, r := range res.Routes {
		if _, seen := aliases[r.ImportPath]; !seen {
			aliases[r.ImportPath] = fmt.Sprintf("r%d", i)
		}
	}
	for i, h := range res.Hooks {
		if _, seen := aliases[h.ImportPath]; !seen {
			aliases[h.ImportPath] = fmt.Sprintf("h%d", i)
		}
	}

	fmt.Fprintf(&b, "%s\n//\n// Regenerate with `pocketkit gen`.\n\npackage %s\n\n", Header, pkgName)

	b.WriteString("import (\n")
	b.WriteString("\t\"github.com/FiretailHosting/pocketkit\"\n")
	if len(res.Hooks) > 0 {
		b.WriteString("\t\"github.com/pocketbase/pocketbase/core\"\n")
	}
	if len(aliases) > 0 {
		b.WriteString("\n")
		imports := make([]string, 0, len(aliases))
		for imp := range aliases {
			imports = append(imports, imp)
		}
		sort.Strings(imports)
		for _, imp := range imports {
			fmt.Fprintf(&b, "\t%s %s\n", aliases[imp], strconv.Quote(imp))
		}
	}
	b.WriteString(")\n\n")

	b.WriteString("func init() {\n")

	if len(res.Routes) > 0 {
		b.WriteString("\tpocketkit.Register(\n")
		for _, r := range res.Routes {
			a := aliases[r.ImportPath]
			fmt.Fprintf(&b, "\t\tpocketkit.RouteDef{\n")
			fmt.Fprintf(&b, "\t\t\tMethod:  %s,\n", strconv.Quote(r.Method))
			fmt.Fprintf(&b, "\t\t\tPath:    %s,\n", strconv.Quote(r.Path))
			fmt.Fprintf(&b, "\t\t\tHandler: %s.%s,\n", a, r.Handler)
			if r.Middlewares != "" {
				fmt.Fprintf(&b, "\t\t\tMiddlewares: %s.%s,\n", a, r.Middlewares)
			}
			if r.Public {
				fmt.Fprintf(&b, "\t\t\tPublic: true,\n")
			}
			fmt.Fprintf(&b, "\t\t},\n")
		}
		b.WriteString("\t)\n")
	}

	if len(res.Hooks) > 0 {
		if len(res.Routes) > 0 {
			b.WriteString("\n")
		}
		b.WriteString("\tpocketkit.RegisterHooks(\n")
		for _, h := range res.Hooks {
			a := aliases[h.ImportPath]
			args := make([]string, 0, len(h.Tags))
			for _, t := range h.Tags {
				args = append(args, strconv.Quote(t))
			}
			fmt.Fprintf(&b, "\t\tpocketkit.HookDef{\n")
			fmt.Fprintf(&b, "\t\t\tName: %s,\n", strconv.Quote(h.Name))
			if len(h.Tags) > 0 {
				fmt.Fprintf(&b, "\t\t\tTags: []string{%s},\n", strings.Join(args, ", "))
			}
			fmt.Fprintf(&b, "\t\t\tBind: func(app core.App) { app.%s(%s).BindFunc(%s.Handle) },\n",
				h.Name, strings.Join(args, ", "), a)
			fmt.Fprintf(&b, "\t\t},\n")
		}
		b.WriteString("\t)\n")
	}

	b.WriteString("}\n")

	src, err := format.Source(b.Bytes())
	if err != nil {
		return nil, fmt.Errorf("generated source is not valid Go: %w\n\n%s", err, b.String())
	}
	return src, nil
}
